/** Turn a fixture row into a canonical `Company` the way the indexer would. */
export function toCompanyFixture(row: FixtureCompany): Company {
  const primary = normalizeName(row.name);
  const variants = nameVariants(row.name).filter((v) => v !== primary);
  return {
    id: companyId(row.domain ? `d:${row.domain}` : `n:${primary}`),
    name: row.name,
    normalizedName: primary,
    aliases: [...new Set([...(row.aliases ?? []), ...variants])],
    domain: row.domain,
    website: row.domain ? `https://${row.domain}` : undefined,
    industry: row.industry,
    country: row.country,
    city: row.city,
    contactCount: row.contactCount,
    sources: [{ source: "csv1", row: 1 }],
  };
}

export function fixtureCompanies(): Company[] {
  return FIXTURE_COMPANIES.map(toCompanyFixture);
}

